def cash_amount(text):
    """'5000', '₹5,000', 'Rs. 5000/-' → 5000. A reward with any words in it is
    a gift, and gives None."""
    cleaned = (text or '').lower()
    for noise in ('₹', 'rs.', 'rs', 'inr', '/-', 'cash', ',', ' '):
        cleaned = cleaned.replace(noise, '')
    try:
        amount = Decimal(cleaned)
    except InvalidOperation:
        return None
    return amount if amount.is_finite() and amount > 0 else None


def rewards_typed_as_a_number_are_cash(apps, schema_editor):
    """Rewards were free text until they could be cash or a gift. One written
    as nothing but an amount was cash all along."""
    RewardTier = apps.get_model('rewards', 'RewardTier')
    for tier in RewardTier.objects.all():
        amount = cash_amount(tier.reward)
        if amount is not None:
            tier.reward_type, tier.reward_amount, tier.reward = 'cash', amount, ''
            tier.save(update_fields=['reward_type', 'reward_amount', 'reward'])


def cash_back_to_text(apps, schema_editor):
    RewardTier = apps.get_model('rewards', 'RewardTier')
    for tier in RewardTier.objects.filter(reward_type='cash'):
        amount = tier.reward_amount
        tier.reward = '' if not amount else str(int(amount)) if amount == int(amount) else str(amount)
        tier.save(update_fields=['reward'])


